/// <summary>
/// Active method trigger extension.
/// </summary>
/// <returns>Returns int as true/false.</returns>
public int active()
{
    int ret = next active();

    this.enableOrDisableSalesInvoiceReportButtons();

    return ret;
}

/// <summary>
/// Enable or Disable sales invoice report buttons based on condition
/// </summary>
public void enableOrDisableSalesInvoiceReportButtons()
{
    FormRun formRun = this.formRun();

    if (formRun != null && formRun.args().record() is SalesTable)
    {
        SalesTable salesTable = formRun.args().record();

        CustInvoiceJour custInvoiceJourLocal = CustInvoiceJour::findFromSalesId_IN(salesTable.SalesId);

        FormButtonControl salesInvoiceCopy = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, SalesInvoiceCopy));
        FormButtonControl salesInvoiceOriginal = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, SalesInvoiceOriginal));
        FormButtonControl salesInvoice = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, SalesInvoice));

        FormFunctionButtonControl metSalesInvoiceOriginal = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, METSalesInvoiceOriginal));
        FormFunctionButtonControl metSalesInvoiceCopy = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, METSalesInvoiceCopy));
        FormFunctionButtonControl metSalesInvoice = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, METSalesInvoice));

        if (custInvoiceJourLocal && custInvoiceJourLocal.SalesId
            && (METSalesOrderTypes::find(salesTable.METSalesOrderType).SalesOrderTypeID == METConstants::SalesInvoiceChargeOnly
                || salesTable.checkForReturnCreditInvoice()))
        {
            metSalesInvoiceOriginal.visible(true);
            metSalesInvoiceCopy.visible(true);
            metSalesInvoice.visible(true);
            salesInvoiceOriginal.visible(false);
            salesInvoice.visible(false);
            salesInvoiceCopy.visible(false);
        }
        else
        {
            metSalesInvoiceOriginal.visible(false);
            metSalesInvoiceCopy.visible(false);
            metSalesInvoice.visible(false);
            salesInvoiceOriginal.visible(true);
            salesInvoice.visible(true);
            salesInvoiceCopy.visible(true);
        }
    }    
}
